insert into kafaa_skill_change_requests (id, kind, skill_id, title_en, title_ar, proposal, rationale, development, assessment, inclusion, status, proposed_by, proposed_role, proposed_at, votes, first_by, first_decision, second_by, decided_at, change_id, updated_at) values
('scr-001', 'add', null, 'Add "Digital I&C fundamentals"', 'إضافة «أساسيات أجهزة القياس والتحكم الرقمية»', '{"name_en":"Digital I&C fundamentals","name_ar":"أساسيات أجهزة القياس والتحكم الرقمية","description_en":"Explains how digital instrumentation and control differs from analogue, including software qualification, diversity and common-cause failure. Part of Calibration and testing (MP-02).","description_ar":"يشرح كيف تختلف أجهزة القياس والتحكم الرقمية عن التناظرية، بما في ذلك تأهيل البرمجيات والتنوّع وأعطال السبب المشترك. جزء من المعايرة والاختبار (MP-02).","area":"maintenance","competency_id":"mp-02","fs_area":"digital_plant","key_level":2,"decay_class":"standard","owner_role":"engineering","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-001', '2026-06-16T11:00:00Z'),
('scr-002', 'add', null, 'Add "Robotics and remote inspection"', 'إضافة «الروبوتات والفحص عن بُعد»', '{"name_en":"Robotics and remote inspection","name_ar":"الروبوتات والفحص عن بُعد","description_en":"Plans and supervises robot or drone inspections that cut dose and confined-space entry, and judges the quality of what they record. Part of Work package execution (MP-01).","description_ar":"يخطط لعمليات الفحص بالروبوتات أو الطائرات المسيّرة التي تقلّل الجرعة الإشعاعية ودخول الأماكن الضيقة ويشرف عليها، ويقيّم جودة ما تسجّله. جزء من تنفيذ حزم العمل (MP-01).","area":"maintenance","competency_id":"mp-01","fs_area":"digital_plant","key_level":2,"decay_class":"fast","owner_role":"maintenance","source_label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","source_url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-002', '2026-06-16T11:00:00Z'),
('scr-003', 'add', null, 'Add "Digital procurement"', 'إضافة «المشتريات الرقمية»', '{"name_en":"Digital procurement","name_ar":"المشتريات الرقمية","description_en":"Runs purchases through digital portals with traceable quality requirements, supplier evidence and in-country value data. Part of Commercial-grade dedication and CFSI (QA-02).","description_ar":"يُجري عمليات الشراء عبر البوابات الرقمية بمتطلبات جودة قابلة للتتبّع وأدلة من الموردين وبيانات القيمة المحلية المضافة. جزء من اعتماد المواد التجارية والمواد المقلدة والمشبوهة (QA-02).","area":"quality","competency_id":"qa-02","fs_area":"digital_plant","key_level":2,"decay_class":"standard","owner_role":"quality","source_label":"Lightcast Open Skills and Skillabi","source_url":"https://lightcast.io/blog/open-skills-taxonomy"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-003', '2026-06-16T11:00:00Z'),
('scr-004', 'add', null, 'Add "Digital work management (electronic work packages)"', 'إضافة «الإدارة الرقمية للأعمال (حزم العمل الإلكترونية)»', '{"name_en":"Digital work management (electronic work packages)","name_ar":"الإدارة الرقمية للأعمال (حزم العمل الإلكترونية)","description_en":"Executes and closes electronic work packages on a tablet, with signatures, holds and records captured as the work is done. Part of Work package execution (MP-01).","description_ar":"ينفّذ حزم العمل الإلكترونية ويغلقها على جهاز لوحي، مع تسجيل التواقيع ونقاط التوقف والسجلات أثناء تنفيذ العمل. جزء من تنفيذ حزم العمل (MP-01).","area":"maintenance","competency_id":"mp-01","fs_area":"digital_plant","key_level":2,"decay_class":"standard","owner_role":"maintenance","source_label":"Jobs Transformation Maps","source_url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-004', '2026-06-16T11:00:00Z'),
('scr-005', 'add', null, 'Add "Digital operator rounds"', 'إضافة «الجولات التشغيلية الرقمية»', '{"name_en":"Digital operator rounds","name_ar":"الجولات التشغيلية الرقمية","description_en":"Records field readings on a handheld device, responds to out-of-range prompts and attaches photos or notes as evidence. Part of Procedure use and adherence (CO-01).","description_ar":"يسجّل القراءات الميدانية على جهاز محمول، ويستجيب لتنبيهات القيم خارج النطاق، ويرفق الصور أو الملاحظات دليلاً. جزء من استخدام الإجراءات والالتزام بها (CO-01).","area":"operations","competency_id":"co-01","fs_area":"digital_plant","key_level":2,"decay_class":"standard","owner_role":"operations","source_label":"Jobs Transformation Maps","source_url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-005', '2026-06-16T11:00:00Z'),
('scr-006', 'add', null, 'Add "Paper log-sheet rounds"', 'إضافة «الجولات بسجلات ورقية»', '{"name_en":"Paper log-sheet rounds","name_ar":"الجولات بسجلات ورقية","description_en":"Records readings on paper log sheets and transcribes them; still in use while digital rounds are rolled out. Part of Procedure use and adherence (CO-01).","description_ar":"يسجّل القراءات على سجلات ورقية ثم ينقلها؛ ولا يزال مستخدماً إلى أن تُعمَّم الجولات الرقمية. جزء من استخدام الإجراءات والالتزام بها (CO-01).","area":"operations","competency_id":"co-01","fs_area":"digital_plant","key_level":2,"decay_class":"standard","owner_role":"operations","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The plant is moving to digital work management and rounds; the catalogue needs the digital skills alongside the declining paper ones.', 'Developed through the digital work management and digital I&C courses and supervised on-the-job tasks on the new tools.', 'Assessed through the course practical and an observed electronic work-package or digital round, separate from the legacy paper tasks.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-02T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-09T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-16T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-16T11:00:00Z', 'sc-006', '2026-06-16T11:00:00Z'),
('scr-007', 'retire', 'sk-fs-dp-paperwp', 'Retire "Paper work-package handling"', 'إيقاف «التعامل مع حزم العمل الورقية»', '{"replaced_by":"sk-fs-dp-ework"}'::jsonb, 'Electronic work packages replaced paper packages at the end of the rollout; keep the skill readable for history but stop developing it.', 'No new development: the digital work management course covers the replacement skill.', 'No new assessment: electronic work packages are observed on the job.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-16T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-23T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-06-30T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-06-30T11:00:00Z', 'sc-007', '2026-06-30T11:00:00Z'),
('scr-008', 'add', null, 'Add "Phishing awareness"', 'إضافة «الوعي بالتصيّد الاحتيالي»', '{"name_en":"Phishing awareness","name_ar":"الوعي بالتصيّد الاحتيالي","description_en":"Recognises suspicious emails, messages and calls, does not click or reply, and reports them through the normal channel. Part of Digital tools and data literacy (DA-01).","description_ar":"يتعرّف على الرسائل والمكالمات المشبوهة، فلا ينقر ولا يرد، ويبلّغ عنها عبر القناة المعتادة. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"cyber_hygiene","key_level":1,"decay_class":"fast","owner_role":"cyber_awareness","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'All staff need cyber hygiene as awareness content, kept separate from security roles (path only).', 'Developed through the all-staff cyber hygiene awareness module and the yearly refresher; awareness level only.', 'Assessed with the awareness quiz per behaviour (phishing, media, zones, access, reporting); no security arrangements are tested.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-23T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-30T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-07-07T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-07-07T11:00:00Z', 'sc-008', '2026-07-07T11:00:00Z'),
('scr-009', 'add', null, 'Add "Removable media discipline"', 'إضافة «الانضباط في استخدام الوسائط القابلة للإزالة»', '{"name_en":"Removable media discipline","name_ar":"الانضباط في استخدام الوسائط القابلة للإزالة","description_en":"Uses only approved, checked portable media and never connects personal devices where they are not allowed. Part of Digital tools and data literacy (DA-01).","description_ar":"لا يستخدم إلا الوسائط المحمولة المعتمدة والمفحوصة، ولا يوصل أجهزته الشخصية حيث لا يُسمح بذلك. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"cyber_hygiene","key_level":1,"decay_class":"fast","owner_role":"cyber_awareness","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'All staff need cyber hygiene as awareness content, kept separate from security roles (path only).', 'Developed through the all-staff cyber hygiene awareness module and the yearly refresher; awareness level only.', 'Assessed with the awareness quiz per behaviour (phishing, media, zones, access, reporting); no security arrangements are tested.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-23T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-30T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-07-07T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-07-07T11:00:00Z', 'sc-009', '2026-07-07T11:00:00Z'),
('scr-010', 'add', null, 'Add "Zone-and-conduit awareness"', 'إضافة «الوعي بمفهوم المناطق والقنوات»', '{"name_en":"Zone-and-conduit awareness","name_ar":"الوعي بمفهوم المناطق والقنوات","description_en":"Explains, in general terms, why plant and office networks are kept apart and why only approved connections may cross between them. Part of Digital tools and data literacy (DA-01).","description_ar":"يشرح بعبارات عامة لماذا تُفصل شبكات المحطة عن شبكات المكاتب، ولماذا لا يُسمح إلا بالاتصالات المعتمدة بينها. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"cyber_hygiene","key_level":1,"decay_class":"fast","owner_role":"cyber_awareness","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'All staff need cyber hygiene as awareness content, kept separate from security roles (path only).', 'Developed through the all-staff cyber hygiene awareness module and the yearly refresher; awareness level only.', 'Assessed with the awareness quiz per behaviour (phishing, media, zones, access, reporting); no security arrangements are tested.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-23T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-30T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-07-07T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-07-07T11:00:00Z', 'sc-010', '2026-07-07T11:00:00Z'),
('scr-011', 'add', null, 'Add "Password and access hygiene"', 'إضافة «النظافة في كلمات المرور وصلاحيات الوصول»', '{"name_en":"Password and access hygiene","name_ar":"النظافة في كلمات المرور وصلاحيات الوصول","description_en":"Uses strong, unique passwords and multi-factor sign-in, never shares accounts and locks the screen when away. Part of Digital tools and data literacy (DA-01).","description_ar":"يستخدم كلمات مرور قوية وفريدة وتسجيل دخول متعدد العوامل، ولا يشارك حساباته أبداً، ويقفل الشاشة عند الابتعاد. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"cyber_hygiene","key_level":1,"decay_class":"fast","owner_role":"cyber_awareness","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'All staff need cyber hygiene as awareness content, kept separate from security roles (path only).', 'Developed through the all-staff cyber hygiene awareness module and the yearly refresher; awareness level only.', 'Assessed with the awareness quiz per behaviour (phishing, media, zones, access, reporting); no security arrangements are tested.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-23T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-30T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-07-07T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-07-07T11:00:00Z', 'sc-011', '2026-07-07T11:00:00Z'),
('scr-012', 'add', null, 'Add "Reporting a suspected cyber incident"', 'إضافة «الإبلاغ عن حادث سيبراني مشتبه به»', '{"name_en":"Reporting a suspected cyber incident","name_ar":"الإبلاغ عن حادث سيبراني مشتبه به","description_en":"Knows that any suspected cyber problem is reported at once through the normal channel, without investigating it themselves. Part of Digital tools and data literacy (DA-01).","description_ar":"يعرف أن أي مشكلة سيبرانية مشتبه بها يُبلَّغ عنها فوراً عبر القناة المعتادة، دون أن يحقق فيها بنفسه. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"cyber_hygiene","key_level":1,"decay_class":"fast","owner_role":"cyber_awareness","source_label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","source_url":"https://www.iaea.org/node/97473"}'::jsonb, 'All staff need cyber hygiene as awareness content, kept separate from security roles (path only).', 'Developed through the all-staff cyber hygiene awareness module and the yearly refresher; awareness level only.', 'Assessed with the awareness quiz per behaviour (phishing, media, zones, access, reporting); no security arrangements are tested.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-06-23T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-06-30T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-07-07T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-07-07T11:00:00Z', 'sc-012', '2026-07-07T11:00:00Z'),
('scr-013', 'add', null, 'Add "Analytical thinking"', 'إضافة «التفكير التحليلي»', '{"name_en":"Analytical thinking","name_ar":"التفكير التحليلي","description_en":"Breaks a plant problem into causes and evidence, weighs options against safety margins and explains the reasoning in writing. Part of Conservative decision-making (LD-02).","description_ar":"يفكّك مشكلة في المحطة إلى أسباب وأدلة، ويوازن الخيارات مقابل هوامش السلامة، ويشرح استدلاله كتابةً. جزء من اتخاذ القرارات المتحفظة (LD-02).","area":"leadership","competency_id":"ld-02","fs_area":"transversal","key_level":3,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-013', '2026-07-21T11:00:00Z'),
('scr-014', 'add', null, 'Add "Systems thinking"', 'إضافة «التفكير المنظومي»', '{"name_en":"Systems thinking","name_ar":"التفكير المنظومي","description_en":"Traces how a change in one system, team or contract ripples through defence in depth, and flags interactions others miss. Part of Defence in depth and safety functions (NS-01).","description_ar":"يتتبّع كيف ينتقل أثر تغيير في نظام أو فريق أو عقد عبر طبقات الدفاع في العمق، وينبّه إلى تفاعلات يغفلها الآخرون. جزء من الدفاع في العمق ووظائف السلامة (NS-01).","area":"safety","competency_id":"ns-01","fs_area":"transversal","key_level":3,"decay_class":"slow","owner_role":"safety_licensing","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-014', '2026-07-21T11:00:00Z'),
('scr-015', 'add', null, 'Add "Resilience, flexibility and agility"', 'إضافة «المرونة والقدرة على التكيّف وسرعة الاستجابة»', '{"name_en":"Resilience, flexibility and agility","name_ar":"المرونة والقدرة على التكيّف وسرعة الاستجابة","description_en":"Stays effective through outages, shift changes and new technology, recovers from setbacks and keeps procedure discipline under pressure. Part of Core human performance tools (HU-01).","description_ar":"يحافظ على فعاليته خلال فترات الانقطاع وتغيّر الورديات والتقنيات الجديدة، ويتعافى من الانتكاسات ويلتزم بالإجراءات تحت الضغط. جزء من الأدوات الأساسية للأداء البشري (HU-01).","area":"human_performance","competency_id":"hu-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-015', '2026-07-21T11:00:00Z'),
('scr-016', 'add', null, 'Add "Curiosity and lifelong learning"', 'إضافة «الفضول والتعلّم مدى الحياة»', '{"name_en":"Curiosity and lifelong learning","name_ar":"الفضول والتعلّم مدى الحياة","description_en":"Seeks out new knowledge and operating experience, asks why, and turns what is learned into changed practice. Part of Questioning attitude and raising concerns (SC-01).","description_ar":"يبحث عن المعارف الجديدة وخبرات التشغيل، ويسأل عن الأسباب، ويحوّل ما يتعلّمه إلى ممارسة متغيّرة. جزء من موقف التساؤل ورفع المخاوف (SC-01).","area":"human_performance","competency_id":"sc-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-016', '2026-07-21T11:00:00Z'),
('scr-017', 'add', null, 'Add "Creative thinking"', 'إضافة «التفكير الإبداعي»', '{"name_en":"Creative thinking","name_ar":"التفكير الإبداعي","description_en":"Generates and tests new ways of working within the licensing basis, separating improvement ideas from changes that need design control. Part of Configuration management and design control (EN-01).","description_ar":"يولّد طرق عمل جديدة ويختبرها ضمن أساس الترخيص، ويميّز أفكار التحسين عن التغييرات التي تتطلب ضبط التصميم. جزء من إدارة التهيئة وضبط التصميم (EN-01).","area":"engineering","competency_id":"en-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"engineering","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-017', '2026-07-21T11:00:00Z'),
('scr-018', 'add', null, 'Add "Technological literacy"', 'إضافة «الإلمام التقني»', '{"name_en":"Technological literacy","name_ar":"الإلمام التقني","description_en":"Picks up new digital tools quickly, understands what they do and where they can fail, and uses them within approved boundaries. Part of Digital tools and data literacy (DA-01).","description_ar":"يتقن الأدوات الرقمية الجديدة بسرعة، ويفهم ما تفعله وأين قد تخفق، ويستخدمها ضمن الحدود المعتمدة. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"transversal","key_level":2,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-018', '2026-07-21T11:00:00Z'),
('scr-019', 'add', null, 'Add "Leadership and social influence"', 'إضافة «القيادة والتأثير الاجتماعي»', '{"name_en":"Leadership and social influence","name_ar":"القيادة والتأثير الاجتماعي","description_en":"Builds commitment to safety and change across teams, including people they do not manage, and models the behaviours they ask for. Part of Leading effective teams (LD-01).","description_ar":"يبني الالتزام بالسلامة والتغيير عبر الفرق، بما في ذلك من لا يديرهم مباشرة، ويكون قدوة في السلوكيات التي يطلبها. جزء من قيادة فرق فعّالة (LD-01).","area":"leadership","competency_id":"ld-01","fs_area":"transversal","key_level":3,"decay_class":"slow","owner_role":"leadership_development","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-019', '2026-07-21T11:00:00Z'),
('scr-020', 'add', null, 'Add "Environmental stewardship"', 'إضافة «الإشراف البيئي»', '{"name_en":"Environmental stewardship","name_ar":"الإشراف البيئي","description_en":"Considers environmental impact in daily decisions, from effluents and waste to energy use, and raises improvement ideas. Part of Radiochemistry and effluent monitoring (CH-02).","description_ar":"يراعي الأثر البيئي في قراراته اليومية، من الانبعاثات السائلة والنفايات إلى استهلاك الطاقة، ويطرح أفكاراً للتحسين. جزء من الكيمياء الإشعاعية ورصد المخلفات (CH-02).","area":"radiation_chemistry","competency_id":"ch-02","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"sustainability","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-020', '2026-07-21T11:00:00Z'),
('scr-021', 'add', null, 'Add "Dependability and attention to detail"', 'إضافة «الموثوقية والدقة في التفاصيل»', '{"name_en":"Dependability and attention to detail","name_ar":"الموثوقية والدقة في التفاصيل","description_en":"Delivers what was agreed, to the letter of the procedure, and catches small discrepancies before they become events. Part of Procedure use and adherence (CO-01).","description_ar":"ينجز ما اتُّفق عليه بحرفية الإجراء، ويلتقط التباينات الصغيرة قبل أن تتحول إلى أحداث. جزء من استخدام الإجراءات والالتزام بها (CO-01).","area":"operations","competency_id":"co-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-021', '2026-07-21T11:00:00Z'),
('scr-022', 'add', null, 'Add "Empathy and active listening"', 'إضافة «التعاطف والإصغاء الفعّال»', '{"name_en":"Empathy and active listening","name_ar":"التعاطف والإصغاء الفعّال","description_en":"Listens to understand, checks back what was heard and adapts how they communicate to the person and the situation. Part of Shift turnover and communications (CO-02).","description_ar":"يُصغي ليفهم، ويتحقق مما سمعه، ويكيّف أسلوب تواصله مع الشخص والموقف. جزء من تسليم النوبات والاتصالات (CO-02).","area":"operations","competency_id":"co-02","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-022', '2026-07-21T11:00:00Z'),
('scr-023', 'add', null, 'Add "Motivation and self-awareness"', 'إضافة «الدافعية والوعي الذاتي»', '{"name_en":"Motivation and self-awareness","name_ar":"الدافعية والوعي الذاتي","description_en":"Knows their own limits and error traps, asks for help early and keeps themselves fit for duty and for learning. Part of Core human performance tools (HU-01).","description_ar":"يعرف حدوده ومواطن الخطأ لديه، ويطلب المساعدة مبكراً، ويحافظ على جاهزيته للعمل والتعلّم. جزء من الأدوات الأساسية للأداء البشري (HU-01).","area":"human_performance","competency_id":"hu-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"human_performance","source_label":"WEF Future of Jobs Report 2025","source_url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-023', '2026-07-21T11:00:00Z'),
('scr-024', 'add', null, 'Add "Collaboration across cultures"', 'إضافة «التعاون بين الثقافات»', '{"name_en":"Collaboration across cultures","name_ar":"التعاون بين الثقافات","description_en":"Works effectively in mixed Emirati, Korean and international teams, bridging language and working styles without losing precision. Part of Leading effective teams (LD-01).","description_ar":"يعمل بفعالية في فرق تجمع كوادر إماراتية وكورية ودولية، ويجسر فروق اللغة وأساليب العمل دون أن يفقد الدقة. جزء من قيادة فرق فعّالة (LD-01).","area":"leadership","competency_id":"ld-01","fs_area":"transversal","key_level":2,"decay_class":"slow","owner_role":"leadership_development","source_label":"OECD-NEA NEST Framework and Plan 2035","source_url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}'::jsonb, 'The WEF core skills appear in role profiles for 2030; they need their own catalogue entries to be evidenced and developed.', 'Developed through the human skills studio practice, leadership journeys and coaching, each behaviour with its own practice set.', 'Assessed through situational judgement practice and behaviourally anchored ratings, separate from the technical skills.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-07-07T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-07-14T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-07-21T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-07-21T11:00:00Z', 'sc-024', '2026-07-21T11:00:00Z'),
('scr-025', 'add', null, 'Add "Everyday use of approved AI tools"', 'إضافة «الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة»', '{"name_en":"Everyday use of approved AI tools","name_ar":"الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة","description_en":"Uses approved AI assistants for drafting, search and summarising, keeps protected information out of them and labels AI-assisted work. Part of Governed use of AI (DA-02).","description_ar":"يستخدم مساعدي الذكاء الاصطناعي المعتمدين في الصياغة والبحث والتلخيص، ويُبقي المعلومات المحمية بعيداً عنهم، ويوسم العمل المُنجز بمساعدتهم. جزء من الاستخدام المحوكم للذكاء الاصطناعي (DA-02).","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","source_url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-025', '2026-08-11T11:00:00Z'),
('scr-026', 'add', null, 'Add "AI output verification and challenge"', 'إضافة «التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها»', '{"name_en":"AI output verification and challenge","name_ar":"التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها","description_en":"Checks AI outputs against procedures and plant data, recognises plausible but wrong answers, and stops or challenges before acting. Part of Governed use of AI (DA-02).","description_ar":"يتحقق من مخرجات الذكاء الاصطناعي مقابل الإجراءات وبيانات المحطة، ويتعرّف على الإجابات المقنعة الخاطئة، ويتوقف أو يعترض قبل التصرّف. جزء من الاستخدام المحوكم للذكاء الاصطناعي (DA-02).","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":3,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","source_url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-026', '2026-08-11T11:00:00Z'),
('scr-027', 'add', null, 'Add "Prompt and agent literacy"', 'إضافة «الإلمام بصياغة الأوامر والوكلاء الذكيين»', '{"name_en":"Prompt and agent literacy","name_ar":"الإلمام بصياغة الأوامر والوكلاء الذكيين","description_en":"Writes clear, bounded instructions for AI assistants and agents, sets limits on what an agent may do, and reviews each step it takes. Part of Governed use of AI (DA-02).","description_ar":"يكتب تعليمات واضحة ومحددة لمساعدي الذكاء الاصطناعي ووكلائه، ويضع حدوداً لما يجوز للوكيل فعله، ويراجع كل خطوة يتخذها. جزء من الاستخدام المحوكم للذكاء الاصطناعي (DA-02).","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"ADNOC AI upskilling and EGA Academy","source_url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-027', '2026-08-11T11:00:00Z'),
